<template><view class="craft-photo" :class="{compact}"><image :src="resolved" mode="aspectFill" lazy-load @error="failed=true"/><text v-if="(!src||failed)&&!compact" class="photo-note">{{label}} · 品类参考图</text></view></template>
<script setup>import{computed,ref,watch}from'vue';import{API_BASE_URL}from'../utils/config';const props=defineProps({src:String,category:String,compact:Boolean});const failed=ref(false);watch(()=>props.src,()=>failed.value=false);const kind=computed(()=>/线|编|绣|染/.test(props.category||'')?'yarn':/陶|泥/.test(props.category||'')?'clay':'paper');const label=computed(()=>({paper:'纸艺灵感',yarn:'纤维与织物',clay:'陶土与器物'}[kind.value]));const resolved=computed(()=>!props.src||failed.value?'/static/library/'+kind.value+'.jpg':/^https?:|^\/static\//.test(props.src)?props.src:API_BASE_URL+props.src)</script>
<style scoped>.craft-photo{position:relative;height:310rpx;width:100%;border-radius:22rpx;overflow:hidden;background:var(--zy-bg-tint-mint);margin-bottom:22rpx}.craft-photo image{width:100%;height:100%;display:block}.photo-note{position:absolute;bottom:14rpx;left:14rpx;color:#fff;background:#173e31cf;padding:6rpx 13rpx;font-size:var(--zy-text-micro, 22rpx);border-radius:8rpx}.craft-photo.compact{height:100%;margin:0;border-radius:inherit}</style>
